<?php
// Reuse the read-only metadata fixture; all options and database mutation methods throw.
require __DIR__.'/assets-metadata.test.php';
function no_assets(){global $fixture;unset($fixture['enqueued'],$fixture['inline']);XI_Conversions::assets();check(!isset($fixture['enqueued'])&&!isset($fixture['inline']),'blocked mode enqueued a sender');}
run_case('legacy raw absent mode preserves service assets and does not install bridge',function(){global $fixture;$before=$fixture['config'];$pub=capture();check($pub['purpose_consent_enabled']===false,'absent flag changed mode');check($fixture['enqueued']['deps']===array(),'legacy service mode installed bridge');check(XI_Conversions::purpose_mode_status()===array('mode_configured'=>false,'mode'=>'service'),'default concealed absent raw key');check($before===$fixture['config'],'read changed options');});
foreach(array('HJ','HT') as $site)run_case($site.' already-purpose absent raw key blocks upgrade preflight',function()use($site){$s=XI_Conversions::purpose_mode_status();check(!($s['mode_configured']&&$s['mode']==='purpose'),$site.' absent key was accepted as purpose-ready');});
run_case('purpose explicit true publishes strict bool and ordered bridge dependency',function(){global $fixture;$fixture['config']['purpose_consent_enabled']=true;$fixture['config']['gtm_id']='GTM-HJF1X';$pub=capture();check($pub['purpose_consent_enabled']===true&&$pub['gtm_id']==='GTM-HJF1X','purpose public configuration mismatch');check($fixture['enqueued']['deps']===array('xi-purpose-consent'),'purpose script dependency missing');check(XI_Conversions::purpose_mode_status()===array('mode_configured'=>true,'mode'=>'purpose'),'explicit purpose status missing');});
run_case('purpose missing owner schema never restores legacy assets',function(){global $fixture;$fixture['config']['purpose_consent_enabled']=true;XI_Conversions::$owner_schema=false;no_assets();});
run_case('purpose missing GTM never enqueues a sender',function(){global $fixture;$fixture['config']['purpose_consent_enabled']=true;$fixture['config']['gtm_id']='';no_assets();});
run_case('invalid raw mode never enqueues a sender',function(){global $fixture;$fixture['config']['purpose_consent_enabled']='true';no_assets();check(XI_Conversions::purpose_mode_status()['mode']==='invalid','invalid string became service mode');});
run_case('explicit false remains service mode even with an available GTM id',function(){global $fixture;$fixture['config']['purpose_consent_enabled']=false;$pub=capture();check($pub['purpose_consent_enabled']===false&&$fixture['enqueued']['deps']===array(),'false mode migrated itself');});
echo "8 purpose mode asset/preflight cases passed.\n";
